ValidationRule.errorConditionFormula:
OR(
    /* Primary phone, India or no country: exactly 10 digits */
    AND(
        NOT(ISBLANK(Phone__c)),
        OR(ISBLANK(TEXT(Country__c)), ISPICKVAL(Country__c, "India")),
        NOT(REGEX(Phone__c, "^[0-9]{10}$"))
    ),
    /* Primary phone, other country: digits only */
    AND(
        NOT(ISBLANK(Phone__c)),
        NOT(ISBLANK(TEXT(Country__c))),
        NOT(ISPICKVAL(Country__c, "India")),
        NOT(REGEX(Phone__c, "^[0-9]+$"))
    ),
    /* Secondary phone, India (own country, or inherited from primary): exactly 10 digits */
    AND(
        NOT(ISBLANK(Secondary_Phone__c)),
        OR(
            ISPICKVAL(Secondary_Country__c, "India"),
            AND(
                ISBLANK(TEXT(Secondary_Country__c)),
                OR(ISBLANK(TEXT(Country__c)), ISPICKVAL(Country__c, "India"))
            )
        ),
        NOT(REGEX(Secondary_Phone__c, "^[0-9]{10}$"))
    ),
    /* Secondary phone, other country (own, or inherited from primary): digits only */
    AND(
        NOT(ISBLANK(Secondary_Phone__c)),
        OR(
            AND(NOT(ISBLANK(TEXT(Secondary_Country__c))), NOT(ISPICKVAL(Secondary_Country__c, "India"))),
            AND(
                ISBLANK(TEXT(Secondary_Country__c)),
                NOT(ISBLANK(TEXT(Country__c))),
                NOT(ISPICKVAL(Country__c, "India"))
            )
        ),
        NOT(REGEX(Secondary_Phone__c, "^[0-9]+$"))
    )
)
